<?php
session_start(); require_once '../middleware/student.php'; require_once '../config/database.php'; require_once '../helpers/csrf_helper.php'; require_once '../helpers/notification_helper.php'; require_once '../helpers/alert_response_helper.php';
if($_SERVER['REQUEST_METHOD']!=='POST'||!isset($_FILES['signed_pdf'])){header('Location: internship_submissions.php');exit;}
verify_csrf_or_abort();
if (($_POST['confirm_two_signatures'] ?? '') !== '1') { renderSweetAlertResponse('ยังยืนยันไม่ครบ', 'กรุณายืนยันว่าเอกสารมีลายเซ็นอาจารย์ที่ปรึกษาและอาจารย์ประสานงานครบแล้ว', 'warning', 'internship_submissions.php', 422); }
$file=$_FILES['signed_pdf']; if($file['error']!==UPLOAD_ERR_OK||$file['size']>10*1024*1024){renderSweetAlertResponse('อัปโหลดไม่สำเร็จ','กรุณาเลือกไฟล์ PDF ที่มีขนาดไม่เกิน 10 MB','warning','internship_submissions.php',422);}
$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']); if($mime!=='application/pdf'){renderSweetAlertResponse('ชนิดไฟล์ไม่ถูกต้อง','รองรับเฉพาะไฟล์ PDF เท่านั้น','warning','internship_submissions.php',422);}
$documentId=(int)($_POST['document_id']??0);
$stmt=$pdo->prepare('SELECT ia.internship_application_id,ia.document_id,s.student_number,s.firstname,s.lastname,g.department_id FROM internship_application ia JOIN internship_profile ip ON ip.internship_profile_id=ia.internship_profile_id JOIN student s ON s.student_id=ip.student_id JOIN group_class g ON g.group_id=s.group_id JOIN documents d ON d.document_id=ia.document_id WHERE s.user_id=? AND ip.request_status="active" AND ia.status="waiting_signature" AND d.document_status IN ("approved","submitted") AND (?=0 OR ia.document_id=?) LIMIT 1');$stmt->execute([$_SESSION['user_id'],$documentId,$documentId]);$app=$stmt->fetch(PDO::FETCH_ASSOC);if(!$app){renderSweetAlertResponse('ยังส่งเอกสารไม่ได้','เอกสารยังไม่ผ่านการพิจารณาครบทุกขั้นตอน','warning','internship_submissions.php',409);}
$dir=__DIR__.'/../uploads/internship_signed';if(!is_dir($dir)&&!mkdir($dir,0775,true)){renderSweetAlertResponse('อัปโหลดไม่สำเร็จ','ระบบไม่สามารถเตรียมพื้นที่จัดเก็บไฟล์ได้','error','internship_submissions.php',500);}
$name='RMUTI_Pro-Ex_02_'.preg_replace('/[^A-Za-z0-9_-]/','_',$app['student_number']).'_'.date('YmdHis').'.pdf';if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name)){renderSweetAlertResponse('อัปโหลดไม่สำเร็จ','ระบบไม่สามารถจัดเก็บไฟล์ได้ กรุณาลองใหม่อีกครั้ง','error','internship_submissions.php',500);}
$pdo->beginTransaction();try{$pdo->prepare('UPDATE internship_application SET signed_file=?,status="submitted",submitted_at=NOW() WHERE internship_application_id=?')->execute([$name,$app['internship_application_id']]);$pdo->prepare('UPDATE documents SET document_status="approved",updated_at=NOW() WHERE document_id=?')->execute([$app['document_id']]);$pdo->prepare('INSERT INTO document_events(document_id,actor_user_id,event_type,detail) VALUES (?,? ,"submitted","อัปโหลด RMUTI_Pro-Ex_02 ที่อาจารย์ที่ปรึกษาและอาจารย์ประสานงานลงนามครบแล้ว")')->execute([$app['document_id'],$_SESSION['user_id']]);notifyDepartmentStaffForInternship($pdo,(int)$app['department_id'],(int)$app['document_id'],(string)$app['student_number'],trim((string)$app['firstname'].' '.(string)$app['lastname']));$pdo->commit();header('Location: internship_submissions.php?submitted=1');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();@unlink($dir.'/'.$name);error_log('Signed internship submission failed: '.$e->getMessage());renderSweetAlertResponse('ส่งเอกสารไม่สำเร็จ','ระบบไม่สามารถส่งเอกสารได้ กรุณาลองใหม่อีกครั้ง','error','internship_submissions.php',500);}

